const WISHLIST_KEY = 'brunito-wishlist-v1';
const productCache = new Map();

const readState = (key) => {
  try {
    const value = JSON.parse(window.localStorage.getItem(key) || '[]');
    return Array.isArray(value) ? value : [];
  } catch {
    return [];
  }
};

const writeState = (key, value) => {
  try {
    window.localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch {
    return false;
  }
};
const escapeHtml = (value = '') => String(value).replace(/[&<>'"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[character]);
const money = (amount) => {
  const rawAmount = typeof amount === 'string' ? amount.replace(',', '.') : amount;
  const cents = typeof amount === 'string' && /[.,]/.test(amount) ? Number(rawAmount) * 100 : Number(rawAmount);
  return new Intl.NumberFormat(document.documentElement.lang || 'es-ES', { style: 'currency', currency: window.Shopify?.currency?.active || 'EUR' }).format((cents || 0) / 100);
};

async function getProduct(handle) {
  if (!handle) return null;
  if (!productCache.has(handle)) {
    productCache.set(handle, fetch(`/products/${encodeURIComponent(handle)}.js`)
      .then((response) => response.ok ? response.json() : null)
      .catch(() => null));
  }
  return productCache.get(handle);
}

function getSelectedVariantId(source) {
  const context = source.closest('.brunito-approved-product, .product-details, quick-add-component');
  return context?.querySelector('form [name="id"]')?.value || source.dataset.productVariantId || '';
}

function positionProductWishlist() {
  document.querySelectorAll('.brunito-product-tools[data-brunito-product-tools]').forEach((tools) => {
    if (tools.dataset.brunitoWishlistPositioned === 'true') return;

    const productForm = tools.parentElement?.querySelector('product-form-component');
    const formButtons = productForm?.querySelector('.product-form-buttons');
    const quantity = formButtons?.querySelector('.quantity-selector-wrapper');
    if (!formButtons || !quantity) return;

    const row = document.createElement('div');
    row.className = 'brunito-product-purchase-row';
    quantity.before(row);
    row.append(quantity, tools);
    tools.dataset.brunitoWishlistPositioned = 'true';
  });
}

function updateProductTools() {
  const wishlist = readState(WISHLIST_KEY);
  document.querySelectorAll('[data-brunito-product-tools]').forEach((tools) => {
    const isSaved = wishlist.some((item) => item.handle === tools.dataset.productHandle);
    const button = tools.querySelector('[data-brunito-wishlist-toggle]');
    const label = tools.querySelector('[data-brunito-wishlist-label]');
    if (button) button.setAttribute('aria-pressed', String(isSaved));
    if (label) label.textContent = isSaved ? 'Guardado en mi wishlist' : 'Añadir a mi wishlist';
  });
}

function updateHeaderWishlist({ pulse = false } = {}) {
  const count = readState(WISHLIST_KEY).length;
  document.querySelectorAll('[data-brunito-wishlist-count]').forEach((badge) => {
    badge.textContent = count > 99 ? '99+' : String(count);
    badge.classList.toggle('hidden', count === 0);
  });
  document.querySelectorAll('[data-brunito-wishlist-open]').forEach((button) => {
    button.setAttribute('aria-label', count ? `Abrir mi wishlist, ${count} producto${count === 1 ? '' : 's'}` : 'Abrir mi wishlist');
  });
  if (!pulse) return;
  document.querySelectorAll('.brunito-header-wishlist__icon').forEach((icon) => {
    icon.classList.remove('is-pulsing');
    void icon.offsetWidth;
    icon.classList.add('is-pulsing');
    window.setTimeout(() => icon.classList.remove('is-pulsing'), 520);
  });
}

function wishlistCard(item, product) {
  const variant = product.variants.find((candidate) => String(candidate.id) === String(item.variantId)) || product.variants.find((candidate) => candidate.available) || product.variants[0];
  const image = product.featured_image || product.images?.[0] || '';
  return `<article class="brunito-wishlist-cart__item">
    ${image ? `<a href="/products/${encodeURIComponent(product.handle)}"><img src="${escapeHtml(image)}" alt="${escapeHtml(product.title)}"></a>` : ''}
    <div class="brunito-wishlist-cart__item-details">
      <a class="brunito-wishlist-cart__item-title" href="/products/${encodeURIComponent(product.handle)}">${escapeHtml(product.title)}</a>
      <span class="brunito-wishlist-cart__item-price">${money(variant?.price || product.price)}</span>
      <div class="brunito-wishlist-cart__actions">
        <button class="brunito-wishlist-cart__add" type="button" data-brunito-wishlist-add data-variant-id="${escapeHtml(variant?.id || '')}">Añadir al carrito</button>
        <button class="brunito-wishlist-cart__remove" type="button" data-brunito-wishlist-remove data-handle="${escapeHtml(product.handle)}">Eliminar</button>
      </div>
    </div>
  </article>`;
}

async function renderWishlistTargets() {
  const targets = [...document.querySelectorAll('[data-brunito-wishlist-cart-items], [data-brunito-wishlist-modal-content]')];
  if (!targets.length) return;
  const wishlist = readState(WISHLIST_KEY);
  if (!wishlist.length) {
    targets.forEach((target) => target.innerHTML = '<p class="brunito-wishlist-cart__empty">Aún no tienes productos guardados. Añade tus favoritos desde cualquier producto.</p>');
    return;
  }
  targets.forEach((target) => target.innerHTML = '<p class="brunito-wishlist-cart__empty">Cargando tus favoritos…</p>');
  const products = await Promise.all(wishlist.map(async (item) => ({ item, product: await getProduct(item.handle) })));
  const cards = products.filter(({ product }) => product).map(({ item, product }) => wishlistCard(item, product)).join('') || '<p class="brunito-wishlist-cart__empty">No se han podido cargar tus favoritos.</p>';
  targets.forEach((target) => target.innerHTML = cards);
}

function saveWishlist(tools) {
  const handle = tools.dataset.productHandle;
  if (!handle) return;
  const wishlist = readState(WISHLIST_KEY);
  const index = wishlist.findIndex((item) => item.handle === handle);
  const status = tools.querySelector('[data-brunito-tools-status]');
  if (index >= 0) {
    wishlist.splice(index, 1);
    if (status) status.textContent = 'Producto eliminado de tu wishlist.';
  } else {
    wishlist.push({ handle, variantId: getSelectedVariantId(tools) });
    if (status) status.textContent = 'Producto guardado en tu wishlist.';
  }
  writeState(WISHLIST_KEY, wishlist);
  updateProductTools();
  updateHeaderWishlist({ pulse: index < 0 });
  renderWishlistTargets();
}

async function addWishlistProductToCart(button) {
  const variantId = button.dataset.variantId;
  if (!variantId) return;
  button.disabled = true;
  button.textContent = 'Añadiendo…';
  try {
    const response = await fetch('/cart/add.js', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ items: [{ id: Number(variantId), quantity: 1 }] }),
    });
    if (!response.ok) throw new Error('cart-add-failed');
    window.location.assign(window.Theme?.routes?.cart_url || '/cart');
  } catch {
    button.disabled = false;
    button.textContent = 'No se ha podido añadir. Inténtalo de nuevo';
  }
}

document.addEventListener('click', (event) => {
  const target = event.target instanceof Element ? event.target : null;
  if (!target) return;
  const toggle = target.closest('[data-brunito-wishlist-toggle]');
  if (toggle) {
    const tools = toggle.closest('[data-brunito-product-tools]');
    if (tools) saveWishlist(tools);
    return;
  }
  if (target.closest('[data-brunito-wishlist-open]')) {
    const dialog = document.querySelector('[data-brunito-wishlist-dialog]');
    if (dialog && !dialog.open) dialog.showModal();
    renderWishlistTargets();
    return;
  }
  if (target.closest('[data-brunito-wishlist-close]')) {
    document.querySelector('[data-brunito-wishlist-dialog]')?.close();
    return;
  }
  const remove = target.closest('[data-brunito-wishlist-remove]');
  if (remove) {
    writeState(WISHLIST_KEY, readState(WISHLIST_KEY).filter((item) => item.handle !== remove.dataset.handle));
    updateProductTools();
    updateHeaderWishlist();
    renderWishlistTargets();
    return;
  }
  const add = target.closest('[data-brunito-wishlist-add]');
  if (add) addWishlistProductToCart(add);
});

document.addEventListener('DOMContentLoaded', () => {
  positionProductWishlist();
  document.querySelectorAll('.product-details').forEach((details) => {
    new MutationObserver(positionProductWishlist).observe(details, { childList: true, subtree: true });
  });
  updateProductTools();
  updateHeaderWishlist();
  if (readState(WISHLIST_KEY).length) renderWishlistTargets();
});
